/*
 * Linker version script: export h_errno with the GLIBC_PRIVATE version tag.
 *
 * Kindle's system libresolv.so.2 (glibc 2.20) expects h_errno@GLIBC_PRIVATE,
 * but our bundled ld-linux (glibc 2.42) no longer provides it.  By exporting
 * this symbol from gst-play itself, we satisfy the dynamic linker at runtime.
 *
 * See gst-play.c for the corresponding __asm__(".symver ...") definition.
 */
GLIBC_PRIVATE {
    global:
        h_errno;
};
